r:1px solid #c6baa3;background:#eee7d8;font-size:38px}.toast{position:absolute;left:50%;bottom:-45px;transform:translateX(-50%);background:#713d46;color:white;padding:8px 12px;border-radius:3px;font-family:Arial,sans-serif;font-size:11px;opacity:0;transition:.2s}.toast.show{opacity:1}
